/**
 * The layout-index adapter answers every `AnchorAxisView` query exactly as the
 * array model in `helpers/array-anchor-axis.ts` does for the same layout, on
 * layouts generated by the real layout operations; plus the workbook context
 * and prospective-coordinate lookups built on it.
 */

import { describe, expect, it } from 'vitest';
import {
    anchor_worksheet,
    column_anchor_axis,
    formula_anchor_context,
    formula_anchor_workbook,
    prospective_cell_at,
    prospective_column_of,
    prospective_row_count,
    prospective_row_of,
    row_anchor_axis,
} from '../formula-anchor-layout';
import { anchor_formula, render_formula, type AnchorAxisView } from '../formula-anchors';
import type { RowIdentity } from '../pending-changes';
import {
    delete_columns,
    delete_rows,
    insert_columns,
    insert_rows,
    move_columns,
    move_rows,
    restore_columns,
    restore_rows,
    source_column_layout,
    source_row_layout,
    type ColumnIdentity,
    type ColumnLayout,
    type RowLayout,
} from '../worksheet-layout';
import {
    column_axis,
    row_axis,
    type AxisMember,
    type AxisModel,
} from './helpers/array-anchor-axis';

function mulberry32(seed: number): () => number {
    let state = seed >>> 0;
    return () => {
        state = (state + 0x6d2b79f5) >>> 0;
        let t = state;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

const pick = <T>(random: () => number, values: readonly T[]): T =>
    values[Math.floor(random() * values.length)]!;

/** Full order of a row layout as array members: 1-based numbers for source rows, ids for pending ones. */
function row_model(
    layout: RowLayout,
    fixed: number,
    source: number,
    band: readonly string[],
    extra_tombstones: readonly number[] = [],
): AxisModel {
    const order: AxisMember[] = [];
    for (const run of layout.runs) {
        if (run.kind === 'source') {
            for (let row = run.start; row < run.start + run.count; row++) order.push(row + 1);
        } else {
            order.push(...run.ids);
        }
    }
    const tombstones = new Set<AxisMember>(layout.discardedPendingRows.map((row) => row.id));
    for (const interval of layout.removedSourceRows) {
        for (let row = interval.start; row < interval.start + interval.count; row++) tombstones.add(row + 1);
    }
    for (const row of extra_tombstones) tombstones.add(row + 1);
    return { fixed, source, order, tombstones, band };
}

function column_model(layout: ColumnLayout, source: number): AxisModel {
    const order = layout.columns.map((column): AxisMember =>
        column.kind === 'source' ? column.sourceColumn + 1 : column.pendingColumnId);
    const tombstones = new Set<AxisMember>([
        ...layout.removedSourceColumns.map((column) => column + 1),
        ...layout.discardedPendingColumns.map((column) => column.id),
    ]);
    return { fixed: 0, source, order, tombstones, band: [] };
}

/** Every query of both views, over every position, number, and identity they could be asked about. */
function expect_same_answers<I>(
    actual: AnchorAxisView<I>,
    expected: AnchorAxisView<I>,
    identities: readonly I[],
): void {
    expect({
        fixedCount: actual.fixedCount,
        sourceCount: actual.sourceCount,
        liveCount: actual.liveCount,
        fullCount: actual.fullCount,
        bandCount: actual.bandCount,
        hasLiveChange: actual.hasLiveChange,
        hasInsertOrOutOfOrderRun: actual.hasInsertOrOutOfOrderRun,
    }).toEqual({
        fixedCount: expected.fixedCount,
        sourceCount: expected.sourceCount,
        liveCount: expected.liveCount,
        fullCount: expected.fullCount,
        bandCount: expected.bandCount,
        hasLiveChange: expected.hasLiveChange,
        hasInsertOrOutOfOrderRun: expected.hasInsertOrOutOfOrderRun,
    });
    for (const identity of identities) {
        expect(actual.position_of(identity)).toBe(expected.position_of(identity));
        if (expected.position_of(identity) !== undefined) {
            expect(actual.in_displaced_run(identity)).toBe(expected.in_displaced_run(identity));
        }
    }
    const end = expected.fullCount + expected.bandCount + 2;
    for (let position = 0; position < end; position++) {
        expect(actual.is_live(position)).toBe(expected.is_live(position));
        if (expected.is_live(position)) {
            expect(actual.prospective_number(position)).toBe(expected.prospective_number(position));
        }
        for (let last = position; last < end; last++) {
            expect(actual.first_live(position, last)).toBe(expected.first_live(position, last));
            expect(actual.last_live(position, last)).toBe(expected.last_live(position, last));
        }
    }
    const last_number = expected.fixedCount + expected.liveCount + expected.bandCount + 2;
    for (let number = 0; number <= last_number; number++) {
        expect(actual.identity_at(number)).toEqual(expected.identity_at(number));
    }
}

interface GeneratedRows {
    readonly layout: RowLayout;
    readonly band: readonly string[];
    readonly identities: readonly RowIdentity[];
}

function generate_rows(random: () => number, body_start: number, body_rows: number): GeneratedRows {
    let layout = source_row_layout(body_start, body_rows);
    const live: RowIdentity[] = Array.from({ length: body_rows }, (_, index) => ({
        kind: 'source',
        sourceRow: body_start + index,
    }));
    const known: RowIdentity[] = [...live];
    const removed: number[] = [];
    const created = new Map<string, number>();
    let next_id = 0;
    const steps = 1 + Math.floor(random() * 8);
    for (let step = 0; step < steps; step++) {
        const action = random();
        if (live.length === 0) break;
        if (action < 0.3) {
            const ids = Array.from({ length: 1 + Math.floor(random() * 2) }, () => `i${next_id++}`);
            const result = insert_rows(layout, pick(random, live), random() < 0.5 ? 'before' : 'after', ids);
            if (!result.ok) continue;
            layout = result.layout;
            for (const id of ids) {
                created.set(id, created.size);
                const identity: RowIdentity = { kind: 'pending', pendingRowId: id };
                live.push(identity);
                known.push(identity);
            }
        } else if (action < 0.6 && live.length > 1) {
            const target = pick(random, live);
            const result = delete_rows(layout, [target], (id) => created.get(id)!);
            if (!result.ok) continue;
            layout = result.layout;
            live.splice(live.indexOf(target), 1);
            if (target.kind === 'source') removed.push(target.sourceRow);
        } else if (action < 0.7 && removed.length > 0) {
            const row = removed.splice(Math.floor(random() * removed.length), 1)[0]!;
            const result = restore_rows(layout, [row]);
            if (!result.ok) continue;
            layout = result.layout;
            live.push({ kind: 'source', sourceRow: row });
        } else {
            const moving = pick(random, live);
            const before = random() < 0.2 ? 'end' : pick(random, known);
            const result = move_rows(layout, [moving], before);
            if (result.ok) layout = result.layout;
        }
    }
    const band = Array.from({ length: Math.floor(random() * 3) }, (_, index) => `a${index}`);
    const identities: RowIdentity[] = [
        ...known,
        ...band.map((pendingRowId): RowIdentity => ({ kind: 'pending', pendingRowId })),
        { kind: 'pending', pendingRowId: 'never-minted' },
    ];
    return { layout, band, identities };
}

function generate_columns(random: () => number, source: number): {
    readonly layout: ColumnLayout;
    readonly identities: readonly ColumnIdentity[];
} {
    let layout = source_column_layout(source);
    const live: ColumnIdentity[] = Array.from({ length: source }, (_, sourceColumn) => ({
        kind: 'source',
        sourceColumn,
    }));
    const known = [...live];
    const removed: number[] = [];
    const created = new Map<string, number>();
    let next_id = 0;
    for (let step = 0; step < 6; step++) {
        const action = random();
        if (action < 0.3) {
            const id = `c${next_id++}`;
            const result = insert_columns(layout, pick(random, live), random() < 0.5 ? 'before' : 'after', [id]);
            if (!result.ok) continue;
            layout = result.layout;
            created.set(id, created.size);
            live.push({ kind: 'pending', pendingColumnId: id });
            known.push({ kind: 'pending', pendingColumnId: id });
        } else if (action < 0.6 && live.length > 1) {
            const target = pick(random, live);
            const result = delete_columns(layout, [target], (id) => created.get(id)!);
            if (!result.ok) continue;
            layout = result.layout;
            live.splice(live.indexOf(target), 1);
            if (target.kind === 'source') removed.push(target.sourceColumn);
        } else if (action < 0.7 && removed.length > 0) {
            const column = removed.splice(Math.floor(random() * removed.length), 1)[0]!;
            const result = restore_columns(layout, [column]);
            if (!result.ok) continue;
            layout = result.layout;
            live.push({ kind: 'source', sourceColumn: column });
        } else {
            const result = move_columns(layout, [pick(random, live)], random() < 0.2 ? 'end' : pick(random, known));
            if (result.ok) layout = result.layout;
        }
    }
    return { layout, identities: [...known, { kind: 'pending', pendingColumnId: 'never-minted' }] };
}

describe('row_anchor_axis', () => {
    it('answers every query like the array model on generated layouts', () => {
        const seen = { removed: 0, discarded: 0, inserted: 0, displaced: 0 };
        for (let seed = 1; seed <= 150; seed++) {
            const random = mulberry32(seed);
            const body_start = Math.floor(random() * 3);
            const body_rows = 1 + Math.floor(random() * 6);
            const { layout, band, identities } = generate_rows(random, body_start, body_rows);
            expect_same_answers(
                row_anchor_axis({ bodyStart: body_start, bodyRowCount: body_rows, rowLayout: layout, band }),
                row_axis(row_model(layout, body_start, body_rows, band)),
                identities,
            );
            const view = row_anchor_axis({ bodyStart: body_start, bodyRowCount: body_rows, rowLayout: layout });
            if (layout.removedSourceRows.length > 0) seen.removed++;
            if (layout.discardedPendingRows.length > 0) seen.discarded++;
            if (layout.runs.some((run) => run.kind === 'pending')) seen.inserted++;
            if (view.hasInsertOrOutOfOrderRun && !layout.runs.some((run) => run.kind === 'pending')) seen.displaced++;
        }
        // The generator reaches every kind of layout difference.
        expect(Object.values(seen).every((count) => count >= 5)).toBe(true);
    });

    it('answers like the array model for the source layout, stored or absent', () => {
        const band = ['a0', 'a1'];
        const expected = row_axis(row_model(source_row_layout(1, 4), 1, 4, band));
        const identities: RowIdentity[] = [1, 2, 3, 4].map((sourceRow) => ({ kind: 'source', sourceRow }));
        expect_same_answers(row_anchor_axis({ bodyStart: 1, bodyRowCount: 4, band }), expected, identities);
        expect_same_answers(
            row_anchor_axis({ bodyStart: 1, bodyRowCount: 4, rowLayout: source_row_layout(1, 4), band }),
            expected,
            identities,
        );
    });

    it('answers for a header-only body', () => {
        expect_same_answers(
            row_anchor_axis({ bodyStart: 1, bodyRowCount: 0, band: ['a0'] }),
            row_axis(row_model(source_row_layout(1, 0), 1, 0, ['a0'])),
            [{ kind: 'pending', pendingRowId: 'a0' }],
        );
    });

    it('treats Pending Tail Removals as tombstones that are not a layout change', () => {
        const view = row_anchor_axis({
            bodyStart: 1,
            bodyRowCount: 5,
            band: ['a0'],
            tailRemovedSourceRows: [4, 5],
        });
        expect(view.hasLiveChange).toBe(false);
        expect(view.liveCount).toBe(3);
        // The band follows the retained rows, as Append places it today.
        expect(view.identity_at(5)).toEqual({ kind: 'pending', pendingRowId: 'a0' });
        expect(view.is_live(view.position_of({ kind: 'source', sourceRow: 4 })!)).toBe(false);
    });
});

describe('column_anchor_axis', () => {
    it('answers every query like the array model on generated layouts', () => {
        for (let seed = 1; seed <= 150; seed++) {
            const random = mulberry32(seed * 7919);
            const source = 1 + Math.floor(random() * 6);
            const { layout, identities } = generate_columns(random, source);
            expect_same_answers(
                column_anchor_axis({ sourceColumnCount: source, columnLayout: layout }),
                column_axis(column_model(layout, source)),
                identities,
            );
        }
    });
});

describe('workbook context and prospective coordinates', () => {
    // Header on row 1, body rows 2..6 (source rows 1..5).
    const deleted_row_3 = delete_rows(source_row_layout(1, 5), [{ kind: 'source', sourceRow: 2 }], () => 0);
    const layout = deleted_row_3.ok ? deleted_row_3.layout : source_row_layout(1, 5);
    const workbook = formula_anchor_workbook('xlsx', [
        {
            target: { sheetIndex: 0, sheetName: 'Data' },
            name: 'Data',
            bodyStart: 1,
            sourceRowCount: 6,
            sourceColumnCount: 3,
            changes: { appendedRows: [], tailRemovals: [], rowLayout: layout },
        },
        {
            target: { sheetIndex: 1, sheetName: 'Other' },
            name: 'Other',
            bodyStart: 0,
            sourceRowCount: 3,
            sourceColumnCount: 2,
        },
    ]);

    it('renders and anchors formulas against the layouts', () => {
        expect(render_formula('=SUM(A2:A6)', undefined, formula_anchor_context(workbook, 0)))
            .toEqual({ kind: 'rendered', text: '=SUM(A2:A5)' });
        expect(render_formula('=Data!A4+A1', undefined, formula_anchor_context(workbook, 1)))
            .toEqual({ kind: 'rendered', text: '=Data!A3+A1' });
        const anchored = anchor_formula('=A3', formula_anchor_context(workbook, 0));
        expect(anchored).toEqual({
            kind: 'anchored',
            anchors: {
                references: [{
                    start: 1,
                    end: 3,
                    corners: [{
                        row: { kind: 'identity', row: { kind: 'source', sourceRow: 3 } },
                        column: { kind: 'identity', column: { kind: 'source', sourceColumn: 0 } },
                    }],
                }],
            },
        });
    });

    it('maps prospective cells to identities and back, skipping removed rows', () => {
        const data = workbook.worksheets[0]!;
        expect(prospective_cell_at(data, 0, 1)).toEqual({
            row: { kind: 'fixed', sourceRow: 0 },
            column: { kind: 'source', sourceColumn: 1 },
        });
        expect(prospective_cell_at(data, 2, 0)?.row).toEqual({ kind: 'source', sourceRow: 3 });
        expect(prospective_cell_at(data, 5, 0)).toBeUndefined();
        expect(prospective_cell_at(data, 1, 3)).toBeUndefined();
        expect(prospective_row_of(data, { kind: 'source', sourceRow: 2 })).toBeUndefined();
        expect(prospective_row_of(data, { kind: 'source', sourceRow: 3 })).toBe(2);
        expect(prospective_row_of(data, { kind: 'source', sourceRow: 0 })).toBe(0);
        expect(prospective_column_of(data, { kind: 'source', sourceColumn: 2 })).toBe(2);
        expect(prospective_row_count(data)).toBe(5);
    });

    it('is the identity map for a worksheet with the source layout', () => {
        const other = anchor_worksheet({
            target: { sheetIndex: 0 },
            name: 'S',
            bodyStart: 2,
            sourceRowCount: 9,
            sourceColumnCount: 4,
        });
        for (let row = 0; row < 9; row++) {
            for (let column = 0; column < 4; column++) {
                const cell = prospective_cell_at(other, row, column)!;
                const source_row = cell.row.kind === 'pending' ? undefined : cell.row.sourceRow;
                expect(source_row).toBe(row);
                expect(cell.column).toEqual({ kind: 'source', sourceColumn: column });
            }
        }
    });
});
